import React, { useEffect, useState } from 'react';
import { getCategories, createCategory, updateCategory, deleteCategory } from './api';
import { useToast } from './Toast';

const EMPTY = { name: '', description: '' };

export default function Categories() {
  const [cats,    setCats]    = useState([]);
  const [loading, setLoading] = useState(true);
  const [modal,   setModal]   = useState(null); // null | 'create' | {cat}
  const [form,    setForm]    = useState(EMPTY);
  const [saving,  setSaving]  = useState(false);
  const [delId,   setDelId]   = useState(null);
  const toast = useToast();

  const load = async () => {
    setLoading(true);
    try {
      const r = await getCategories();
      setCats(r.categories || []);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, []);

  function openCreate() { setForm(EMPTY); setModal('create'); }
  function openEdit(c) { setForm({ name: c.name, description: c.description || '' }); setModal(c); }

  async function save() {
    if (!form.name.trim()) return toast('Name is required', 'error');
    setSaving(true);
    try {
      if (modal === 'create') {
        await createCategory(form);
        toast('Category created', 'success');
      } else {
        await updateCategory(modal.id, form);
        toast('Category updated', 'success');
      }
      setModal(null);
      load();
    } catch (e) {
      toast(e.message, 'error');
    } finally {
      setSaving(false);
    }
  }

  async function remove(id) {
    try {
      await deleteCategory(id);
      toast('Category deleted', 'success');
      setDelId(null);
      load();
    } catch (e) {
      toast(e.message, 'error');
    }
  }

  return (
    <div style={styles.page}>
      <div style={styles.header}>
        <div>
          <h1 style={styles.h1}>Categories</h1>
          <p style={{ color:'var(--muted)', fontSize:13 }}>{cats.length} categories</p>
        </div>
        <button className="btn btn-primary" onClick={openCreate}>
          <PlusIcon /> Add Category
        </button>
      </div>

      {loading ? (
        <div style={{ display:'flex', justifyContent:'center', padding:'60px 0' }}><span className="spinner" /></div>
      ) : cats.length === 0 ? (
        <div className="card"><div className="empty"><div className="empty-icon">🏷️</div><p>No categories yet. Add your first one!</p></div></div>
      ) : (
        <div style={styles.grid}>
          {cats.map(c => (
            <div key={c.id} className="card" style={styles.catCard}>
              <div style={styles.catThumb}>
                {c.image_url
                  ? <img src={`http://localhost:5000${c.image_url}`} alt={c.name} style={{ width:'100%', height:'100%', objectFit:'cover' }} />
                  : <TagBig />}
              </div>
              <div style={{ flex:1, minWidth:0 }}>
                <div style={{ fontWeight:600, fontSize:14 }}>{c.name}</div>
                <div style={{ fontSize:11, color:'var(--muted)', marginTop:3 }}>/{c.slug}</div>
                {c.description && (
                  <div style={{ fontSize:12, color:'var(--muted)', marginTop:6, lineHeight:1.5 }} className="truncate">
                    {c.description}
                  </div>
                )}
              </div>
              <div style={{ display:'flex', gap:8, flexShrink:0 }}>
                <button className="btn btn-ghost btn-sm" onClick={() => openEdit(c)}>Edit</button>
                <button className="btn btn-danger btn-sm" onClick={() => setDelId(c.id)}>Delete</button>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Modal */}
      {modal !== null && (
        <div className="overlay" onClick={e => e.target === e.currentTarget && setModal(null)}>
          <div className="modal" style={{ maxWidth:420 }}>
            <h3>{modal === 'create' ? 'New Category' : 'Edit Category'}</h3>
            <div style={{ marginBottom:14 }}>
              <label className="label">Category Name *</label>
              <input className="input" value={form.name} onChange={e => setForm({...form, name:e.target.value})} placeholder="e.g. Dresses" autoFocus />
            </div>
            <div style={{ marginBottom:22 }}>
              <label className="label">Description</label>
              <textarea className="input" rows={3} value={form.description} onChange={e => setForm({...form, description:e.target.value})} placeholder="Short description…" style={{ resize:'vertical' }} />
            </div>
            <div style={{ display:'flex', gap:10, justifyContent:'flex-end' }}>
              <button className="btn btn-ghost" onClick={() => setModal(null)}>Cancel</button>
              <button className="btn btn-primary" onClick={save} disabled={saving}>
                {saving ? <span className="spinner" style={{ width:14, height:14 }} /> : null}
                {modal === 'create' ? 'Create' : 'Save'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Delete Confirm */}
      {delId && (
        <div className="overlay" onClick={e => e.target === e.currentTarget && setDelId(null)}>
          <div className="modal" style={{ maxWidth:340, textAlign:'center' }}>
            <div style={{ fontSize:36, marginBottom:12 }}>⚠️</div>
            <h3 style={{ marginBottom:8 }}>Delete Category?</h3>
            <p style={{ color:'var(--muted)', fontSize:13, marginBottom:24 }}>This may affect products assigned to this category.</p>
            <div style={{ display:'flex', gap:10, justifyContent:'center' }}>
              <button className="btn btn-ghost" onClick={() => setDelId(null)}>Cancel</button>
              <button className="btn btn-danger" onClick={() => remove(delId)}>Delete</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

const styles = {
  page: { padding:'28px 32px', maxWidth:1000 },
  header: { display:'flex', alignItems:'flex-start', justifyContent:'space-between', marginBottom:24 },
  h1: { fontFamily:"'Playfair Display', serif", fontSize:28, fontWeight:400, color:'var(--text)', marginBottom:4 },
  grid: { display:'flex', flexDirection:'column', gap:10 },
  catCard: { display:'flex', alignItems:'center', gap:16, padding:'14px 18px' },
  catThumb: {
    width:48, height:48, borderRadius:10, background:'var(--surface2)',
    display:'flex', alignItems:'center', justifyContent:'center',
    flexShrink:0, overflow:'hidden',
  },
};

function PlusIcon() {
  return <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>;
